<template><div class="shell"><BranchSidebar active="orders" :new-orders="newCount"/><main><header><div><h1>주문 관리</h1><p>접수 시간이 오래된 주문부터 처리하세요</p></div><div><button @click="oldest=!oldest">☷　{{ oldest?'오래된 순':'최신 순' }}</button><button class="busy" @click="busy=!busy">⚡　{{ busy?'바빠요':'보통' }}</button></div></header>
  <div v-if="busy" class="busy-banner">⚡　<strong>바빠요 활성 — 키오스크에 예상 대기 20분 표시 중</strong><button @click="busy=false">해제</button></div>
  <section><table><thead><tr><th>주문번호</th><th>경과 시간</th><th>유형</th><th>메뉴</th><th>상태</th><th>처리</th></tr></thead><tbody><tr v-for="o in sorted" :key="o.orderId"><td><b>#{{ o.waitingNumber }}</b></td><td><span class="elapsed" :class="o.elapsedMinutes>15?'danger':o.elapsedMinutes>8?'warn':'safe'">{{ o.elapsedMinutes }}분</span></td><td><span class="type" :class="o.orderType.toLowerCase()">{{ o.orderType==='TAKEOUT'?'포장':'매장' }}</span></td><td>{{ o.menu }}</td><td><strong :class="`s-${o.status}`">{{ label(o.status) }}</strong></td><td><div class="actions"><button v-if="o.status==='PAID'" class="start" @click="change(o,'MAKING')">제조 시작</button><button v-if="o.status==='MAKING'" class="complete" @click="change(o,'COMPLETED')">완료</button><button v-if="!['COMPLETED','CANCELLED'].includes(o.status)" class="cancel" @click="change(o,'CANCELLED')">취소</button></div></td></tr></tbody></table><div v-if="!orders.length" class="empty">접수된 주문이 없습니다.</div></section>
  </main></div></template>
<script setup>import{computed,onBeforeUnmount,onMounted,ref}from'vue';import http from'../../api/http';import BranchSidebar from'../../components/branch/BranchSidebar.vue';const orders=ref([]),oldest=ref(true),busy=ref(true);let timer;const newCount=computed(()=>orders.value.filter(o=>o.status==='PAID').length),sorted=computed(()=>[...orders.value].sort((a,b)=>oldest.value?new Date(a.createdAt)-new Date(b.createdAt):new Date(b.createdAt)-new Date(a.createdAt)));function label(s){return({PAID:'신규',MAKING:'처리중',READY:'준비완료',COMPLETED:'완료',CANCELLED:'취소'})[s]||s}async function load(){try{orders.value=(await http.get('/branch/orders')).data}catch(e){console.error(e)}}async function change(o,status){await http.patch(`/branch/orders/${o.orderId}/status`,{status});await load()}onMounted(()=>{load();timer=setInterval(load,2000)});onBeforeUnmount(()=>clearInterval(timer))</script>
<style scoped>.shell{min-height:100vh;color:#202a39;background:#f3f6fa}main{margin-left:238px;padding:31px 34px}header{display:flex;justify-content:space-between;align-items:center}h1{margin:0;font-size:26px}header p{margin:7px 0;color:#7c8796;font-size:11px}header button{padding:10px 15px;border:1px solid #dce1e8;background:#fff;border-radius:10px;color:#566173;font-size:10px;font-weight:800}.busy{margin-left:8px;color:#fff;background:#ff6c11;border-color:#ff6c11}.busy-banner{display:flex;align-items:center;margin:22px 0;padding:15px 17px;color:#d85300;border:1px solid #ffbb80;background:#fff8ef;border-radius:13px;font-size:11px}.busy-banner button{margin-left:auto;color:#d85300;border:0;background:none;font-size:10px}section{overflow:hidden;margin-top:20px;background:#fff;border:1px solid #e0e5ec;border-radius:15px}table{width:100%;border-collapse:collapse}th{padding:14px 18px;color:#747f8f;background:#f8fafc;font-size:10px;text-align:left}td{padding:15px 18px;border-top:1px solid #edf0f4;font-size:10px}td>b{font-size:12px}.elapsed,.type{padding:5px 8px;border-radius:6px;font-weight:800}.danger{color:#ef3948;background:#ffe8eb}.warn{color:#d27c00;background:#fff2cf}.safe{color:#0a9d56;background:#e4f8ed}.type.dine_in{color:#3671e9;background:#eaf1ff}.type.takeout{color:#7253e7;background:#f0ebff}.s-PAID{color:#6165ee}.s-MAKING{color:#dc7200}.s-COMPLETED{color:#0b9c58}.s-CANCELLED{color:#a3a9b2}.actions{display:flex;gap:6px}.actions button{padding:7px 10px;border-radius:7px;font-size:9px;font-weight:800}.start,.complete{color:#0a9c54;border:0;background:#dff8e9}.cancel{color:#ef3e4b;border:1px solid #ffabb1;background:#fff}.empty{padding:60px;text-align:center;color:#9ba3af}@media(max-width:760px){main{margin-left:0;padding:20px}section{overflow:auto}table{min-width:850px}}</style>
